    {
      "service": "attractions",
      "fault_kind": "process_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT avg(value) AS avg_cpu_cores, max(value) AS max_cpu_cores FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'attractions%' AND metric = 'k8s.pod.cpu.usage'",
          "claim": "attractions pod CPU averages about 0.76 cores and pins near 0.82 for the whole abnormal window, versus about 0.0025 normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) FILTER (WHERE service_name = 'attractions') AS attr_server_spans, count(*) FILTER (WHERE span_name LIKE 'attractions.%') AS frontend_to_attractions_spans FROM abnormal_traces",
          "claim": "In the abnormal window attractions produced zero server spans and frontend made zero attractions gRPC calls; normal had 253 and 489."
        }
      ]
    },
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, max(value) AS max_restarts, count(*) AS samples FROM abnormal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name LIKE 'user-%' GROUP BY 1",
          "claim": "The user pod restart counter climbs repeatedly, reaching 6, while the user deployment reports 0 available throughout the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE span_name = 'user.User/CheckUser' GROUP BY ALL",
          "claim": "All 264 frontend calls to user.User/CheckUser error in about 0.02 ms, and user emits zero server spans, versus 299 normally."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Server' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL",
          "claim": "Frontend's /cinema, /museums and /restaurants endpoints return HTTP 500 in about 0.04 ms, the attraction-backed paths failing."
        }
      ]
    },
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Server' AND span_name = 'HTTP /user' GROUP BY ALL",
          "claim": "Frontend's /user endpoint returns HTTP 500 for every request in the abnormal window, matching the failed user calls."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE level = 'ERROR' GROUP BY ALL",
          "claim": "Frontend logs 9 ERROR entries 'User authentication failed' in the abnormal window, none in normal, consistent with the user service being down."
        }
      ]
    }
  ]
}
